    private int _index;
    internal SmallListEnumerator(SmallList<T, TStack> list)
    {
        _list = list;
        _index = -1;
    }
    private T _current;
    /// <inheritdoc />
    public T Current => _current;
    object IEnumerator.Current => _current;
    /// <inheritdoc />
    [MethodImpl((MethodImplOptions)256)]
    public bool MoveNext()
