        var index = ++_index;
        if (index < _list.Count)
        {
            _current = index < _list.Stack.Capacity
                ? _list.Stack.GetSurePresentItemRef(index)
                : _list.Rest[index - _list.Stack.Capacity];
            return true;
        }
        return false;
    }
    /// <inheritdoc />
    public void Reset() => _index = -1;
    /// <inheritdoc />
    public void Dispose() { }
}

